// Locate live declarations after edits, without stale generated byte offsets.
const ts = require('../app/node_modules/typescript');
module.exports = function declaration(text, name) {
  const ast = ts.createSourceFile('live.js', text, ts.ScriptTarget.Latest, true);
  let found;
  function visit(n) {
    if (ts.isFunctionDeclaration(n) && n.name?.text === name && !n.modifiers?.some(m => m.kind === ts.SyntaxKind.ExportKeyword)) found = n;
    if (ts.isVariableStatement(n) && n.declarationList.declarations.some(d => d.name.getText(ast) === name)) found = n;
    ts.forEachChild(n, visit);
  }
  visit(ast);
  if (!found) throw Error('Missing live declaration: ' + name);
  return found.getText(ast);
};
